class Solution:

	def kSubstrConcat(self, n, s, k):
		if n % k != 0:
			return 0
		pat = s[0:k]
		(cnt, cnt2) = (0, 0)
		pat2 = ''
		for i in range(0, n, k):
			if pat == s[i:i + k]:
				cnt += 1
			elif pat2 == '':
				pat2 = s[i:i + k]
				cnt2 += 1
			elif pat2 == s[i:i + k]:
				cnt2 += 1
		if (cnt <= 1 or cnt2 <= 1) and cnt + cnt2 == n // k:
			return 1
		return 0
